import test from 'node:test';import assert from 'node:assert/strict';
import {createPendingWorldChangeGate} from '../tools/trees/prototype_pending_world_change.mjs';
const route={session:'s',actorId:'a',worldVersion:1,version:1,kind:'trajectory',startTime:0,points:[{x:0,z:0},{x:4,z:0}],durations:[4],movementMode:'walk',animationState:'walk'};
function ready(){const g=createPendingWorldChangeGate('s','a',{worldVersion:1});assert.equal(g.install(route,0).accepted,true);g.presented(1);return g;}
test('pending change freezes presentation until matching confirmed stop',()=>{const g=ready();assert.deepEqual(g.begin('one'),{accepted:true,at:1,point:{x:1,z:0}});assert.equal(g.sample(3).x,1);assert.equal(g.sample(3).movementMode,'stopped');assert.throws(()=>g.presented(2));assert.equal(g.confirm('other',{worldVersion:2,version:2,at:1,point:{x:1,z:0}}).reason,'token');assert.equal(g.sample(4).x,1);assert.equal(g.confirm('one',{worldVersion:2,version:2,at:1,point:{x:1,z:0}}).accepted,true);assert.equal(g.sample(10).x,1);assert.equal(g.install({...route,worldVersion:1,version:3},1).reason,'world');});
test('mismatched confirmed point fails closed and cannot resume',()=>{const g=ready();g.begin('one');assert.deepEqual(g.confirm('one',{worldVersion:2,version:2,at:1,point:{x:2,z:0}}),{accepted:false,reason:'position',hide:true});assert.equal(g.sample(3),null);assert.equal(g.begin('two').reason,'pending');});
test('duplicate commands cannot replace the pending token',()=>{const g=ready();g.begin('one');assert.equal(g.begin('two').reason,'pending');assert.equal(g.confirm('two',{}).reason,'token');assert.equal(g.state().pending,true);});
test('missing presentation and malformed responses fail without motion',()=>{const g=createPendingWorldChangeGate('s','a',{worldVersion:1});g.install(route,0);assert.throws(()=>g.begin('one'));g.presented(1);g.begin('one');assert.throws(()=>g.confirm('one',{worldVersion:0,version:2,at:1,point:{x:1,z:0}}));assert.equal(g.sample(3),null);});
test('holding never returns a future pose for an earlier time',()=>{const g=ready();g.begin('one');assert.throws(()=>g.sample(.5),/precedes/);assert.equal(g.sample(1).x,1);});
